import json
from itertools import permutations

def solve():
    houses = range(5)  # indices 0..4 represent houses 1..5

    names_all = ['Arnold', 'Eric', 'Bob', 'Peter', 'Alice']
    smoothies_all = ['desert', 'watermelon', 'lime', 'cherry', 'dragonfruit']
    nats_all = ['german', 'swede', 'norwegian', 'dane', 'brit']

    # Generate permutations with fixed clues applied early
    names_perms = []
    for perm in permutations(names_all):
        # Clue 10: Alice is in the third house (index 2)
        if perm[2] != 'Alice':
            continue
        # Clue 3: Peter is not in the first house (index 0)
        if perm[0] == 'Peter':
            continue
        names_perms.append(perm)

    smoothies_perms = []
    for perm in permutations(smoothies_all):
        # Clue 2: Dragonfruit in second house (index 1)
        if perm[1] != 'dragonfruit':
            continue
        # Clue 11: Watermelon in third house (index 2)
        if perm[2] != 'watermelon':
            continue
        # Clue 5: Desert not in fifth house (index 4)
        if perm[4] == 'desert':
            continue
        smoothies_perms.append(perm)

    nats_perms = []
    for perm in permutations(nats_all):
        # Clue 9: Alice is the Norwegian; since Alice is at index 2,
        # Norwegian must be at index 2
        if perm[2] != 'norwegian':
            continue
        nats_perms.append(perm)

    def pos(seq, value):
        return seq.index(value)

    solutions = []

    for names in names_perms:
        for smoothies in smoothies_perms:
            # Clue 1: Dragonfruit lover is left of Eric
            if pos(smoothies, 'dragonfruit') >= pos(names, 'Eric'):
                continue

            for nats in nats_perms:
                # Clue 8: Bob is the Dane
                if pos(names, 'Bob') != pos(nats, 'dane'):
                    continue

                # Clue 4: Dane and Brit are next to each other
                if abs(pos(nats, 'dane') - pos(nats, 'brit')) != 1:
                    continue

                # Clue 6: Swede is left of Dragonfruit
                if pos(nats, 'swede') >= pos(smoothies, 'dragonfruit'):
                    continue

                # Clue 7: Two houses between Lime and Dane
                if abs(pos(smoothies, 'lime') - pos(nats, 'dane')) != 3:
                    continue

                # All constraints satisfied
                solutions.append((names, smoothies, nats))

    # Choose the first (should be unique)
    if not solutions:
        raise RuntimeError("No solution found")

    names, smoothies, nats = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Smoothie", "Nationality"],
            "rows": [
                [str(i + 1), names[i], smoothies[i], nats[i]] for i in range(5)
            ]
        }
    }
    return result

if __name__ == "__main__":
    solution = solve()
    print(json.dumps(solution))
